from bs4 import BeautifulSoup
from service.db import DB
from service.userAgent import user_agent_list
from service.nameMap import country_type_map, city_name_map, country_name_map, continent_name_map
import re
import json
import time
import random
import logging
import requests


class Crawler:
    def __init__(self):
        self.db = DB()
        self.user_agent_list = user_agent_list
        self.country_type_map = country_type_map
        self.city_name_map = city_name_map
        self.country_name_map = country_name_map
        self.continent_name_map = continent_name_map

    def run(self):
        self.crawler()

    def crawler(self):
        try:
            url = 'https://3g.dxy.cn/newh5/view/pneumonia'
            headers = {
                'User-Agent': random.choice(self.user_agent_list)
            }
            response = requests.get(url, headers=headers)
            soup = BeautifulSoup(response.content, 'lxml')
            overall = soup.find('script', id='getAreaStat')
            abroad = soup.find('script', id='getListByCountryTypeService2')
            news = soup.find('script', id='getTimelineService2')
            rumor = soup.find('script', id='getRumorList')

            overall_data = self.overall_parser(overall)
            province_data = self.province_parser(overall)
            area_data = self.area_parser(overall)
            abroad_data = self.abroad_parser(abroad)
            news_data = self.news_parser(news)
            rumor_data = self.rumor_parser(rumor)

            self.db.insert('overall', overall_data)
            self.db.insert('province', province_data)
            self.db.insert('area', area_data)
            self.db.insert('abroad', abroad_data)
            self.db.insert('news', news_data)
            self.db.insert('rumor', rumor_data)

        except Exception as e:
            logging.error(f"Crawler error: {e}")

    def overall_parser(self, overall_script):
        if not overall_script:
            return {}
        try:
            content = overall_script.string
            json_str = re.search(r'\{(.*?)\}', content).group(0)
            data = json.loads(json_str)
            return data
        except Exception as e:
            logging.error(f"Overall parser error: {e}")
            return {}

    def province_parser(self, overall_script):
        if not overall_script:
            return []
        try:
            content = overall_script.string
            json_str = re.search(r'\[(.*?)\]', content).group(0)
            data = json.loads(json_str)
            return data
        except Exception as e:
            logging.error(f"Province parser error: {e}")
            return []

    def area_parser(self, overall_script):
        if not overall_script:
            return []
        try:
            content = overall_script.string
            json_str = re.search(r'\[(.*?)\]', content).group(0)
            data = json.loads(json_str)
            # Process city names using city_name_map
            for province in data:
                for city in province.get('cities', []):
                    city_name = city.get('cityName', '')
                    if city_name in self.city_name_map:
                        city['cityName'] = self.city_name_map[city_name]
            return data
        except Exception as e:
            logging.error(f"Area parser error: {e}")
            return []

    def abroad_parser(self, abroad_script):
        if not abroad_script:
            return []
        try:
            content = abroad_script.string
            json_str = re.search(r'\[(.*?)\]', content).group(0)
            data = json.loads(json_str)
            # Map country names using country_name_map
            for country in data:
                country_name = country.get('countryName', '')
                if country_name in self.country_name_map:
                    country['countryName'] = self.country_name_map[country_name]
                country_type = country.get('countryType', '')
                if country_type in self.country_type_map:
                    country['countryType'] = self.country_type_map[country_type]
            return data
        except Exception as e:
            logging.error(f"Abroad parser error: {e}")
            return []

    def news_parser(self, news_script):
        if not news_script:
            return []
        try:
            content = news_script.string
            json_str = re.search(r'\[(.*?)\]', content).group(0)
            data = json.loads(json_str)
            return data
        except Exception as e:
            logging.error(f"News parser error: {e}")
            return []

    def rumor_parser(self, rumor_script):
        if not rumor_script:
            return []
        try:
            content = rumor_script.string
            json_str = re.search(r'\[(.*?)\]', content).group(0)
            data = json.loads(json_str)
            return data
        except Exception as e:
            logging.error(f"Rumor parser error: {e}")
            return []
